CREATE TABLE IF NOT EXISTS framework_records (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, value TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS framework_records_tenant_idx ON framework_records (tenant_id, id);
CREATE TABLE IF NOT EXISTS framework_idempotency (scope TEXT NOT NULL, key TEXT NOT NULL, fingerprint TEXT NOT NULL, status TEXT NOT NULL, response TEXT, PRIMARY KEY (scope, key));
CREATE TABLE IF NOT EXISTS framework_outbox (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS framework_audit (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, record_id TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS framework_cache_generations (scope TEXT PRIMARY KEY, generation INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS framework_leases (lease_key TEXT PRIMARY KEY, owner TEXT NOT NULL, fence INTEGER NOT NULL, expires_at_ms INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS framework_finalizers (finalizer_key TEXT PRIMARY KEY, owner TEXT NOT NULL, fence INTEGER NOT NULL, state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS framework_inbox_records (record_key TEXT PRIMARY KEY, record TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS framework_outbox_delivery_records (record_key TEXT PRIMARY KEY, record TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS framework_ev1_business_effects (id TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS framework_j1_jobs (id TEXT PRIMARY KEY, worker_id TEXT NOT NULL, claim_token TEXT NOT NULL, attempt INTEGER NOT NULL, lease_expires_at_ms INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS framework_job_progress (job_id TEXT PRIMARY KEY REFERENCES framework_j1_jobs(id) ON DELETE CASCADE, attempt INTEGER NOT NULL, sequence INTEGER NOT NULL, percent REAL, checkpoint TEXT, updated_at_ms INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS framework_workflows (id TEXT PRIMARY KEY, workflow_type TEXT NOT NULL, workflow_version INTEGER NOT NULL, execution_scope TEXT NOT NULL, status TEXT NOT NULL, current_step TEXT NOT NULL, variables TEXT NOT NULL, step_attempt INTEGER NOT NULL DEFAULT 0, compensation_stack TEXT NOT NULL DEFAULT '[]', waiting_signal TEXT, wake_at_ms INTEGER, outcome TEXT, failure TEXT, revision INTEGER NOT NULL DEFAULT 0, lease_owner TEXT, claim_token TEXT, lease_expires_at_ms INTEGER, created_at_ms INTEGER NOT NULL, updated_at_ms INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS framework_workflows_due_idx ON framework_workflows (status, wake_at_ms, lease_expires_at_ms, updated_at_ms);
CREATE TABLE IF NOT EXISTS framework_workflow_signals (id TEXT PRIMARY KEY, instance_id TEXT NOT NULL REFERENCES framework_workflows(id) ON DELETE CASCADE, name TEXT NOT NULL, payload TEXT NOT NULL, delivered_at_ms INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS framework_temporal_heads (scope_id TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, revision INTEGER NOT NULL CHECK (revision > 0), occurred_at_ms INTEGER NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('created','updated','deleted','restored')), PRIMARY KEY (scope_id, entity_type, entity_id));
CREATE TRIGGER IF NOT EXISTS framework_temporal_heads_initial BEFORE INSERT ON framework_temporal_heads WHEN NEW.kind <> 'created' AND NOT EXISTS (SELECT 1 FROM framework_temporal_heads WHERE scope_id=NEW.scope_id AND entity_type=NEW.entity_type AND entity_id=NEW.entity_id) BEGIN SELECT RAISE(ABORT, 'temporal revision stream must begin with creation'); END;
CREATE TRIGGER IF NOT EXISTS framework_temporal_heads_transition BEFORE UPDATE ON framework_temporal_heads WHEN NEW.occurred_at_ms < OLD.occurred_at_ms OR (OLD.kind = 'deleted' AND NEW.kind <> 'restored') OR (OLD.kind <> 'deleted' AND NEW.kind NOT IN ('updated','deleted')) BEGIN SELECT RAISE(ABORT, 'invalid temporal revision transition'); END;
CREATE TABLE IF NOT EXISTS framework_temporal_revisions (scope_id TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, revision INTEGER NOT NULL CHECK (revision > 0), occurred_at_ms INTEGER NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('created','updated','deleted','restored')), state TEXT, entity_version INTEGER, event_id TEXT, audit_id TEXT, CHECK ((kind = 'deleted' AND state IS NULL) OR (kind <> 'deleted' AND state IS NOT NULL)), PRIMARY KEY (scope_id, entity_type, entity_id, revision));
CREATE INDEX IF NOT EXISTS framework_temporal_revisions_time_idx ON framework_temporal_revisions (scope_id, entity_type, entity_id, occurred_at_ms, revision);
CREATE TABLE IF NOT EXISTS framework_temporal_snapshots (scope_id TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, revision INTEGER NOT NULL CHECK (revision >= 0), occurred_at_ms INTEGER NOT NULL, state TEXT, PRIMARY KEY (scope_id, entity_type, entity_id, revision));
CREATE TABLE IF NOT EXISTS framework_sequences (scope_id TEXT NOT NULL, name TEXT NOT NULL, period TEXT NOT NULL, value INTEGER NOT NULL CHECK (value > 0), PRIMARY KEY (scope_id, name, period));
